class Solution {
public:
    bool flipEquiv(TreeNode* root1, TreeNode* root2) {
        if (!root1 || !root2) return root1 == root2;
        if (root1->val != root2->val) return false;
        bool no_flip = flipEquiv(root1->left, root2->left) && flipEquiv(root1->right, root2->right);
        bool flip = flipEquiv(root1->left, root2->right) && flipEquiv(root1->right, root2->left);
        return no_flip || flip;
    }
};

class Solution {
    public boolean flipEquiv(TreeNode root1, TreeNode root2) {
        if (root1 == null || root2 == null) return root1 == root2;
        if (root1.val != root2.val) return false;
        boolean noFlip = flipEquiv(root1.left, root2.left) && flipEquiv(root1.right, root2.right);
        boolean flip = flipEquiv(root1.left, root2.right) && flipEquiv(root1.right, root2.left);
        return noFlip || flip;
    }
}

var flipEquiv = function(root1, root2) {
    if (!root1 || !root2) return root1 === root2;
    if (root1.val !== root2.val) return false;
    const noFlip = flipEquiv(root1.left, root2.left) && flipEquiv(root1.right, root2.right);
    const flip = flipEquiv(root1.left, root2.right) && flipEquiv(root1.right, root2.left);
    return noFlip || flip;
};
